CustomField.formula:
IF(ISNULL(GH_fla_Edad__c), "N/A", 
    IF(GH_fla_Edad__c < 30, "Menor a 30",
        IF(GH_fla_Edad__c <= 40, "30-40",
            IF(GH_fla_Edad__c <= 50, "41-50",
                IF(GH_fla_Edad__c <= 60, "51-60",
                    IF(GH_fla_Edad__c <= 70, "61-70",
                        "Mayor a 70"
                    )
                )
            )
        )
    )
)
